/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[
    error_codes::NOT_FOUND,
    error_codes::NOT_SUSPENDED,
    error_codes::TERMINAL,
];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vtc/relationships/restore:notFound`
    ///
    /// No edge with this id exists that the caller may restore. Returned identically for an unknown edge and for one the caller neither issued nor moderates.
    ///
    /// Declared `retryable: false`.
    pub const NOT_FOUND: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/relationships/restore:notFound",
        retryable: false,
    };
    /// `vtc/relationships/restore:notSuspended`
    ///
    /// The edge is not suspended. Restoration reverses a suspension and nothing else — an edge that is merely expired is restored by re-issuance, not by a lifecycle event.
    ///
    /// Declared `retryable: false`.
    pub const NOT_SUSPENDED: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/relationships/restore:notSuspended",
        retryable: false,
    };
    /// `vtc/relationships/restore:terminal`
    ///
    /// The edge was superseded or withdrawn, which is terminal.
    ///
    /// Declared `retryable: false`.
    pub const TERMINAL: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vtc/relationships/restore:terminal",
        retryable: false,
    };
}
